Projection.hosp_stay_schedule:
def hosp_stay_schedule():
    """The mean-stay rows of the model's basis, keyed by age_from."""
    return data.hosp_stay_table().loc[hosp_stay_basis()]

Projection.hosp_stay_basis:
def hosp_stay_basis():
    """The mean-stay basis chosen by ``hosp_age_gradient``: the age bands or all ages."""
    return StayBasis.age_band if hosp_age_gradient else StayBasis.all_ages
